import React, { useState } from "react";
import {
  Users, Briefcase, CalendarDays, BarChart3, Bell, FileText, MessageCircle, Settings, Sun, Moon
} from "lucide-react";

const OfficerDashboard = () => {
  const [darkMode, setDarkMode] = useState(true);
  const [activeTab, setActiveTab] = useState("STUDENTS");

  const tabs = [
    { name: "STUDENTS", icon: Users },
    { name: "POSTINGS", icon: Briefcase },
    { name: "EVENTS", icon: CalendarDays },
    { name: "COMPANIES", icon: FileText },
    { name: "REPORTS", icon: BarChart3 },
    { name: "NOTIFICATIONS", icon: Bell },
    { name: "QUERIES", icon: MessageCircle },
    { name: "PROFILE", icon: Settings }
  ];

  return (
    <div className={darkMode ? "bg-gray-900 text-white min-h-screen" : "bg-gray-100 text-gray-900 min-h-screen"}>
      {/* Navbar */}
      <nav className="flex items-center justify-between px-8 py-4 border-b">
        <div className="flex items-center gap-3">
          <Briefcase className="h-8 w-8 text-cyan-400" />
          <span className="font-bold text-2xl text-cyan-400">Placement Cell Officer</span>
        </div>
        <div className="flex items-center gap-6">
          <button onClick={() => setDarkMode(!darkMode)} aria-label="Toggle theme">
            {darkMode ? <Sun className="h-6 w-6 text-yellow-400" /> : <Moon className="h-6 w-6 text-gray-700" />}
          </button>
          <img src="https://randomuser.me/api/portraits/men/45.jpg" alt="Officer" className="h-10 w-10 rounded-full border-2 border-cyan-400" />
        </div>
      </nav>

      {/* Sidebar Tabs */}
      <div className="flex">
        <aside className="w-56 bg-gray-800/90 min-h-screen border-r border-cyan-400 py-8">
          <ul>
            {tabs.map(tab => {
              const Icon = tab.icon;
              return (
                <li key={tab.name} className="mb-2">
                  <button
                    className={`flex items-center gap-3 px-6 py-3 w-full rounded-xl font-semibold transition-all duration-200
                      ${activeTab === tab.name ? "bg-cyan-400/20 text-cyan-400 border-2 border-cyan-400" : "text-gray-300 hover:bg-gray-700"}
                    `}
                    onClick={() => setActiveTab(tab.name)}
                    aria-label={tab.name}
                  >
                    <Icon className={`h-5 w-5 ${activeTab === tab.name ? "text-cyan-400" : "text-gray-400"}`} />
                    {tab.name}
                  </button>
                </li>
              );
            })}
          </ul>
        </aside>

        {/* Main Content */}
        <main className="flex-1 p-10">
          {/* Dashboard Widgets */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-8 mb-10">
            <div className="bg-gray-800 rounded-2xl p-6 flex flex-col items-center shadow-lg">
              <Users className="h-8 w-8 text-cyan-400 mb-2" />
              <span className="text-2xl font-bold">1200</span>
              <span className="text-gray-400">Total Students</span>
            </div>
            <div className="bg-gray-800 rounded-2xl p-6 flex flex-col items-center shadow-lg">
              <Briefcase className="h-8 w-8 text-cyan-400 mb-2" />
              <span className="text-2xl font-bold">45</span>
              <span className="text-gray-400">Active Postings</span>
            </div>
            <div className="bg-gray-800 rounded-2xl p-6 flex flex-col items-center shadow-lg">
              <BarChart3 className="h-8 w-8 text-cyan-400 mb-2" />
              <span className="text-2xl font-bold">87%</span>
              <span className="text-gray-400">Placement Rate</span>
            </div>
            <div className="bg-gray-800 rounded-2xl p-6 flex flex-col items-center shadow-lg">
              <CalendarDays className="h-8 w-8 text-cyan-400 mb-2" />
              <span className="text-2xl font-bold">3</span>
              <span className="text-gray-400">Upcoming Events</span>
            </div>
          </div>

          {/* Tab Content */}
          {activeTab === "STUDENTS" && (
            <section>
              <h2 className="text-xl font-bold mb-4 text-cyan-400">Student Management</h2>
              {/* Search/filter, table, export, bulk email */}
              {/* ... */}
            </section>
          )}
          {activeTab === "POSTINGS" && (
            <section>
              <h2 className="text-xl font-bold mb-4 text-cyan-400">Job/Internship Postings</h2>
              {/* Add/edit/delete, view applications, download resumes */}
              {/* ... */}
            </section>
          )}
          {activeTab === "EVENTS" && (
            <section>
              <h2 className="text-xl font-bold mb-4 text-cyan-400">Event Management</h2>
              {/* Calendar, RSVP, attendance */}
              {/* ... */}
            </section>
          )}
          {activeTab === "COMPANIES" && (
            <section>
              <h2 className="text-xl font-bold mb-4 text-cyan-400">Company Management</h2>
              {/* Add/edit, view history, feedback */}
              {/* ... */}
            </section>
          )}
          {activeTab === "REPORTS" && (
            <section>
              <h2 className="text-xl font-bold mb-4 text-cyan-400">Reports & Analytics</h2>
              {/* Charts, downloadable reports */}
              {/* ... */}
            </section>
          )}
          {activeTab === "NOTIFICATIONS" && (
            <section>
              <h2 className="text-xl font-bold mb-4 text-cyan-400">Notifications & Announcements</h2>
              {/* Send, schedule, view notifications */}
              {/* ... */}
            </section>
          )}
          {activeTab === "QUERIES" && (
            <section>
              <h2 className="text-xl font-bold mb-4 text-cyan-400">Feedback & Queries</h2>
              {/* View/respond to queries, feedback */}
              {/* ... */}
            </section>
          )}
          {activeTab === "PROFILE" && (
            <section>
              <h2 className="text-xl font-bold mb-4 text-cyan-400">Officer Profile</h2>
              {/* Update profile, password, photo */}
              {/* ... */}
            </section>
          )}
        </main>
      </div>
    </div>
  );
};

export default OfficerDashboard;
